function applyClassRoster() {
  const classIds = new Set(classUpdates.map(course => course.id));
  const existingCourses = new Map(db.courses.map(course => [course.id, course]));
  db.courses = [
    ...classUpdates.map(update => ({...existingCourses.get(update.id), ...update})),
    ...db.courses.filter(course => !classIds.has(course.id)),
  ];
  db.enrolled = [...new Set([...classIds, ...db.enrolled])];

  const sampleReminder = db.posts.find(post => post.id === 'p2' && post.author === 'Prof. Li Rui');
  if (sampleReminder) {
    sampleReminder.author = 'SPM Studio';
    sampleReminder.initials = 'SP';
  }
}

applyClassRoster();
