function cover(c){let art=c.color==='lavender'?`<svg viewBox="0 0 180 160"><g transform="translate(28 22)"><path d="M0 25l70-18 49 39-68 22z" fill="#ad9ad8"/><path d="M0 25v25l51 43V68z" fill="#c2b2e4"/><path d="M51 68l68-22v25L51 93z" fill="#8e77bd"/><path d="M11 72l70-18 49 39-68 22z" fill="#d1c5eb"/><path d="M11 72v22l51 43v-22z" fill="#b6a3da"/><path d="M62 115l68-22v22-22 22l-68 22z" fill="#9a84c5"/><path d="M35 18l17 13M53 13l18 14M70 8l18 14" stroke="#e3d9f4" stroke-width="3"/></g></svg>`:c.color==='mint'?`<svg viewBox="0 0 180 160"><ellipse cx="95" cy="126" rx="60" ry="13" fill="#b5d6c8"/><g fill="none" stroke-width="13"><ellipse cx="90" cy="77" rx="50" ry="29" stroke="#76ab94" transform="rotate(-28 90 77)"/><ellipse cx="90" cy="77" rx="50" ry="29" stroke="#a2ccba" transform="rotate(35 90 77)"/></g><circle cx="90" cy="77" r="14" fill="#edf8f2"/></svg>`:c.color==='peach'?`<svg viewBox="0 0 180 160"><path d="M48 35l45-15 45 24v54l-45 36-45-28z" fill="#dfb38c"/><path d="M48 35l45 25 45-16-45-24z" fill="#f0d4b9"/><path d="M93 60v74l45-36V44z" fill="#c79265"/><path d="M67 77l13 13 25-30" stroke="#fff5e9" fill="none" stroke-width="6"/></svg>`:`<svg viewBox="0 0 180 160"><ellipse cx="98" cy="133" rx="60" ry="13" fill="#c1d5f3"/><path d="M32 73l45-24 45 26-45 25z" fill="#b3cbef"/><path d="M32 73v28l45 27v-28z" fill="#85a9de"/><path d="M77 100l45-25v27l-45 26z" fill="#5a87cc"/><path d="M68 35l44-25 45 27-45 25z" fill="#d1e1f9"/><path d="M68 35v29l44 26V62z" fill="#9cbce9"/><path d="M112 62l45-25v28l-45 25z" fill="#6f98d7"/><path d="M105 19l21 12M94 26l21 12" stroke="#eff5ff" stroke-width="3"/></svg>`;return `<div class="course-cover ${c.color}"><span class="cover-label">${esc(c.code.split(' ')[0])} / STUDIO</span><span class="cover-chip">${t('COURSE','课程')}</span><span class="cover-number">${esc(c.code)} · ${t('2026 FALL','2026 秋季')}</span><div class="cover-art">${art}</div></div>`}
function render(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.body.classList.toggle('dark',db.theme==='dark');if (!db.user) { renderAuth(); return; } const learning=db.role==='admin'?['dashboard','users',...(db.accounts.some(a=>a.pending)||db.audit.length?['approvals']:[]),'courses','exams','discussions','analytics']:['dashboard','courses','assignments','exams','grades'];const collaboration=db.role==='admin'?['resources','calendar']:['projects','discussions','calendar','resources','analytics'];const nav=n=>`<button class="nav-item ${page===n?'active':''}" onclick="go('${n}')">${icon(({dashboard:'grid',courses:'book',assignments:'clipboard',exams:'file',grades:'award',projects:'folder',discussions:'chat',calendar:'calendar',resources:'folder',analytics:'chart',users:'users',approvals:'shield'})[n])}<span>${db.role==='teacher'&&n==='grades'?t('Gradebook','成绩册'):txt(label[n])}</span>${n==='assignments'?'<span class="count">'+db.assignments.filter(a=>a.status==='pending').length+'</span>':''}${n==='approvals'&&db.accounts.filter(a=>a.pending).length?'<span class="count">'+db.accounts.filter(a=>a.pending).length+'</span>':''}</button>`;$('#app').innerHTML=`<div class="shell"><div class="mobile-overlay" onclick="toggleSidebar()"></div><aside class="sidebar"><a class="brand" href="#" onclick="go('dashboard');return false"><span class="brand-logo">${icon('logo')}</span><div><strong>spm<span style="font-weight:500">studio</span></strong><small>LEARN. BUILD. GROW.</small></div></a><div class="nav-section">${db.role==='admin'?t('PLATFORM','平台管理'):t('LEARNING SPACE','学习空间')}</div><nav>${learning.map(nav).join('')}</nav><div class="nav-section">${t('WORKSPACE','协作空间')}</div><nav>${collaboration.map(nav).join('')}</nav><div class="sidebar-bottom"><div class="semester-card"><div style="display:flex;gap:8px;align-items:center;color:#5c7fbc">${icon('award')}<strong>${t('A little progress, every day.','每天，进步一点点。')}</strong></div><p>${t('Your next big idea starts here.','让下一个好想法从这里开始。')}</p><button class="small-link" onclick="go('projects')">${t('Open your workspace','进入项目空间')}${icon('arrow')}</button></div><div class="sidebar-footer"><button class="nav-item ${page==='profile'?'active':''}" onclick="go('profile')">${icon('settings')}${t('Settings','设置')}</button><button class="nav-item" onclick="help()">${icon('help')}${t('Help & getting started','帮助与入门')}</button></div></div></aside><div class="workspace"><header class="topbar"><button class="icon-button mobile-toggle" onclick="toggleSidebar()" aria-label="${t('Open menu','打开菜单')}">${icon('menu')}</button><div class="breadcrumb">${t('Workspace','工作空间')}${icon('chevron')}<span>${txt(label[page]||label.dashboard)}</span></div><div class="top-actions"><form class="search-top" onsubmit="globalSearch(event)">${icon('search')}<input name="q" aria-label="${t('Search workspace','搜索工作空间')}" placeholder="${t('Search anything...','搜索课程、任务、资源…')}"><span class="key">⌘ K</span></form><span class="demo-label">${t('DEMO WORKSPACE','演示空间')}</span><button class="lang-button" onclick="switchLanguage()" aria-label="${t('Switch to Chinese','切换至英文')}">${icon('globe')}${t('EN','中文')}${icon('down')}</button><button class="icon-button" onclick="notifications()" aria-label="${t('Notifications','通知')}">${icon('bell')}${!db.notificationsRead?'<i class="dot"></i>':''}</button><button class="profile-trigger" onclick="accountMenu()" aria-label="${t('Account menu','账户菜单')}"><span class="avatar">${esc(db.user.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span>${icon('down')}</button></div></header><main class="main">${renderPage()}<footer class="footer"><span>© 2026 SPM Studio · ${t('Made for your next chapter.','为你的下一篇章而生。')}</span><span><i></i>${t('Demo data · saved in this browser','演示数据 · 保存在当前浏览器')}</span></footer></main></div></div>`;wireLabels()}
function go(n){page=n;render();if(n==='users' && db.role==='admin') void loadRosterUsers();window.scrollTo({top:0,behavior:'smooth'})}function toggleSidebar(){$('.sidebar').classList.toggle('open');$('.mobile-overlay').classList.toggle('open')}function switchLanguage(){lang=lang==='en'?'zh':'en';localStorage.setItem('spm-lang',lang);closeModal();render()}
function heading(title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${t('FALL SEMESTER 2026','2026 年秋季学期')} <span style="padding:0 6px;color:#bfc9d8">/</span> ${roleName()}</div><h1>${title}</h1><p>${sub}</p></div>${action||`<span class="date-pill">${icon('calendar')}${t('Wednesday, November 4','11月4日，星期三')}</span>`}</div>`}
function renderPage(){switch(page){case'dashboard':return dashboard();case'courses':return coursesPage();case'assignments':return assignmentsPage();case'exams':return examsPage();case'projects':return projectsPage();case'calendar':return calendarPage();case'resources':return resourcesPage();case'grades':return gradesPage();case'discussions':return discussionsPage();case'analytics':return analyticsPage();case'users':return usersPage();case'approvals':return approvalsPage();case'profile':return profilePage();default:return dashboard()}}
function statCards(){let data=db.role==='student'?[['book',String(db.enrolled.length).padStart(2,'0'),t('Enrolled courses','已选课程'),t('+1 this month','本月 +1')],['chart',Math.round(db.enrolled.reduce((n,id)=>n+(course(id)?progress(course(id)):0),0)/Math.max(db.enrolled.length,1))+'%',t('Overall progress','整体学习进度'),t('Keep it going','继续加油')],['clipboard',String(db.assignments.filter(a=>a.status==='pending').length).padStart(2,'0'),t('Upcoming tasks','即将截止'),t('This week','本周')],['clock','12.5',t('Learning hours','学习时长'),t('+2.5 this week','本周 +2.5')]]:db.role==='teacher'?[['book',String(db.courses.length),t('Your courses','教学课程'),t('This semester','本学期')],['users',String(rosterCounts.students),t('Students on roster','名册学生'),t('Class roster','班级名册')],['clipboard',String(db.assignments.filter(a=>a.status==='submitted').length),t('To be graded','待批改作业'),t('Ready to review','等待评阅')],['chart','86%',t('Class engagement','班级参与度'),t('Sample metric','示例指标')]]:[['users',String(rosterCounts.total),t('Roster members','名册成员'),t('Class roster','班级名册')],['book',String(db.courses.length),t('Available courses','课程数量'),t('This semester','本学期')],['shield',String(rosterCounts.total),t('Registered profiles','已注册账户'),t('Shared roster','共享名册')],['chart','98%',t('Demo activity','演示活跃度'),t('Sample metric','示例指标')]];return `<div class="stats">${data.map(([ic,n,l,b])=>`<div class="stat"><div class="stat-top"><span class="stat-icon">${icon(ic)}</span><span class="trend">${b}</span></div><div class="stat-value">${n}${ic==='clock'?'<small> hrs</small>':''}</div><div class="stat-label">${l}</div></div>`).join('')}</div>`}
function dashboard(){return heading(t(`A good day to grow, ${esc(fullname())} <span style="font-size:24px">✧</span>`,`今天也一起进步，${esc(fullname())} <span style="font-size:24px">✧</span>`),t('A little learning. A little creating. A step closer to your goals.','学一点新知识，创造一点新可能，离目标再近一步。'))+`<div class="dashboard-grid"><div class="left-column"><section class="welcome"><div class="welcome-copy"><div class="eyebrow">${t('YOUR NEXT CHAPTER STARTS HERE','你的下一篇章，从这里开始')}</div><h2>${t('Learn with purpose.<br>Build with confidence.','学有所向。<br>行有所成。')}</h2><p>${t('Great projects start with curious minds. Pick up where you left off and make your next idea happen.','好项目始于好奇心。继续上次的学习，让下一个想法落地成真。')}</p>${btn(t('Continue learning','继续学习'),"openCourse('c1')",'white','play')}</div><div class="hero-art"><svg viewBox="0 0 280 265"><defs><linearGradient id="cubeTop" x2="1" y2="1"><stop stop-color="#79a9ff"/><stop offset="1" stop-color="#4380e8"/></linearGradient></defs><circle cx="175" cy="130" r="116" fill="#234678" opacity=".26"/><path d="M90 116l67-37 68 39-68 39z" fill="url(#cubeTop)"/><path d="M90 116v56l67 40v-55z" fill="#3567ba"/><path d="M157 157l68-39v56l-68 38z" fill="#244e91"/><path d="M116 64l48-27 48 28-48 28z" fill="#b8d2ff"/><path d="M116 64v36l48 28V93z" fill="#7ca8ef"/><path d="M164 93l48-28v36l-48 27z" fill="#4e85de"/><path d="M157 168v27M171 161v27M185 153v27" stroke="#6d9fe8" stroke-width="2"/><path d="M68 92v14M61 99h14M237 183v10M232 188h10" stroke="#7da8ef" stroke-width="2"/><circle cx="229" cy="68" r="4" fill="#5d8bdb"/><circle cx="88" cy="211" r="3" fill="#719ce3"/></svg></div></section>${statCards()}<div class="section-heading"><h2>${db.role==='teacher'?t('Your teaching space','你的教学空间'):t('Continue learning','继续学习')}</h2><button class="small-link" onclick="go('courses')">${t('View all courses','查看全部课程')}${icon('arrow')}</button></div><div class="courses-grid">${db.courses.slice(0,2).map(courseCard).join('')}</div><div class="lower-grid"><section><div class="section-heading"><h2>${t('Your team project','你的小组项目')}</h2><button class="small-link" onclick="go('projects')">${t('Open workspace','进入空间')}${icon('arrow')}</button></div><div class="panel project-mini"><div class="project-mini-header"><div class="project-symbol">${icon('folder')}</div><div><h3>${t('SPM Learning Platform','SPM 智慧学习平台')}</h3><p>${t('Team Horizon · 4 members','Horizon 小组 · 4名成员')}</p></div></div><div class="members"><span class="avatar">OL</span><span class="avatar blue">YW</span><span class="avatar green">MC</span><span class="avatar purple">JW</span><small>${t('Building something better, together.','一起，创造更好的可能。')}</small></div><div class="progress-meta"><span>${t('Sprint 02 progress','第02轮迭代进度')}</span><strong>${Math.round(db.tasks.filter(a=>a.status===2).length/db.tasks.length*100)}%</strong></div><div class="progress-track"><span style="width:${db.tasks.filter(a=>a.status===2).length/db.tasks.length*100}%"></span></div><div class="course-footer"><span>${icon('flag')} ${t('Next milestone: Nov 8','下个里程碑：11月8日')}</span><span>${db.tasks.filter(a=>a.status===2).length}/${db.tasks.length} ${t('tasks','任务')}</span></div></div></section><section><div class="section-heading"><h2>${t('Recent activity','最近动态')}</h2><span class="muted" style="font-size:9px">${t('THIS WEEK','本周')}</span></div><div class="panel" style="padding-top:5px">${[[t('New chapter: Project scope management','新章节：项目范围管理'),t('Project Management and Process Improvement · 2 hours ago','项目管理与过程改进 · 2小时前')],[t('Your requirements analysis was graded','你的需求分析作业已评分'),t('Score: 92 / 100 · Yesterday','成绩：92 / 100 · 昨天')],[t('Team Horizon completed a milestone','Horizon 小组完成了一个里程碑'),t('Team formation · Nov 2','团队组建 · 11月2日')]].map(([a,b])=>`<div class="activity-row"><i class="activity-dot"></i><div><strong>${a}</strong><small>${b}</small></div></div>`).join('')}</div></section></div></div><aside class="right-column"><section class="panel">${miniCalendar()}<div class="schedule-divider"></div><div class="section-heading"><h2>${t("Today's schedule",'今日日程')}</h2><span class="badge blue">${t('2 events','2项日程')}</span></div><div class="event-row"><div><strong>${t('Project scope management','项目范围管理')}</strong><small>${t('SPM 301 · Lecture','SPM 301 · 课程讲授')}</small></div><span class="time">14:00</span></div><div class="event-row purple"><div><strong>${t('Team Horizon check-in','Horizon 小组例会')}</strong><small>${t('Project workspace · Online','项目空间 · 线上')}</small></div><span class="time">19:30</span></div></section><section class="panel"><div class="section-heading"><h2>${t('Coming up next','即将截止')}</h2><button class="small-link" onclick="go('assignments')">${t('View all','全部')}${icon('arrow')}</button></div>${db.assignments.filter(a=>a.status==='pending').slice(0,3).map((a,i)=>`<button class="deadline" style="text-align:left;width:100%" onclick="openAssignment('${a.id}')"><span class="deadline-icon">${icon(a.type==='quiz'?'clipboard':'file')}</span><div><strong>${esc(txt(a.title))}</strong><p>${esc(txt(course(a.course)?.title||''))}</p><span class="badge ${i===0?'orange':'blue'}">${t('Due','截止')} ${formatDate(a.due)}</span></div></button>`).join('')||`<p class="muted">${t('You are all caught up. Well done!','所有任务都完成了，真棒！')}</p>`}</section><section class="announcement">${icon('chat')}<h3>${t('Weekly report reminder','项目周报提醒')}</h3><p>${t('Your first weekly report is about direction, not perfection. Start with a clear scope and a shared plan.','第一次周报重在明确方向。清晰的项目范围与团队共识，是最好的起点。')}</p><button class="small-link" onclick="go('discussions')">${t('Read announcement','阅读公告')}${icon('arrow')}</button></section></aside></div>`}
function courseCard(c){const en=db.enrolled.includes(c.id),p=progress(c),published=publishedIndices(c),done=published.filter(i=>completedUnits(c).includes(i)).length;return `<article class="course-card">${cover(c)}<div class="course-body"><div class="course-category">${esc(txt(c.category))}</div><h3>${esc(txt(c.title))}</h3><div class="instructor">${icon('user')}${esc(txt(c.teacher))}</div><div class="progress-meta"><span>${c.draft?t('Draft · visible to instructors','草稿 · 仅教师可见'):en?t('Course progress','课程进度'):t('Open for enrollment','开放选课')}</span><strong>${en?p+'%':published.length+' '+t('lessons','课时')}</strong></div><div class="progress-track"><span style="width:${en?p:0}%"></span></div><div class="course-footer"><span>${icon('book')} ${en?done+' / ':''}${published.length} ${t('lessons','课时')}</span><button class="small-link" onclick="openCourse('${c.id}')">${c.draft?t('Preview','预览'):en?t('Continue','继续学习'):t('Explore course','了解课程')}${icon('arrow')}</button></div></div></article>`}
function coursesPage(){let list=db.courses.filter(c=>db.role!=='student'||!c.draft).filter(c=>courseTab==='catalog'||db.enrolled.includes(c.id)||db.role!=='student').filter(c=>(txt(c.title)+' '+txt(c.teacher)).toLowerCase().includes(courseSearch.toLowerCase()));return heading(db.role==='teacher'?t('Your classroom, reimagined.','焕新你的课堂。'):t('A world of new possibilities.','探索知识的无限可能。'),t('Build knowledge that takes your ideas further.','积累知识，让想法走得更远。'),db.role==='teacher'?btn(t('Create course','创建课程'),"createCourse()",'primary','plus'):'')+`<div class="tabs"><button class="${courseTab==='enrolled'?'active':''}" onclick="courseTab='enrolled';render()">${db.role==='teacher'?t('My teaching','我的教学'):t('My courses','我的课程')} <span class="muted">${db.role==='teacher'?db.courses.length:db.enrolled.length}</span></button><button class="${courseTab==='catalog'?'active':''}" onclick="courseTab='catalog';render()">${t('Explore catalog','探索课程')}</button></div><div class="toolbar"><input id="course-search" aria-label="${t('Search courses','搜索课程')}" placeholder="${t('Search courses or instructors...','搜索课程或教师…')}" value="${esc(courseSearch)}" oninput="filterCourses(this.value)"><select aria-label="${t('Course category','课程分类')}" onchange="courseSearch=this.value;render()"><option value="">${t('All categories','所有分类')}</option><option value="${t('project','项目')}">${t('Project management','项目管理')}</option><option value="${t('software','软件')}">${t('Software engineering','软件工程')}</option><option value="${t('agile','敏捷')}">${t('Agile development','敏捷开发')}</option></select><span class="muted" style="margin-left:auto;font-size:11px">${list.length} ${t('courses','门课程')}</span></div><div class="courses-grid full-courses" id="course-list">${list.map(courseCard).join('')||emptyState(t('No courses found','未找到课程'),t('Try another search or explore the catalog.','尝试其他关键词或浏览课程中心。'))}</div>`}
function filterCourses(v){courseSearch=v;const list=db.courses.filter(c=>db.role!=='student'||!c.draft).filter(c=>courseTab==='catalog'||db.enrolled.includes(c.id)||db.role!=='student').filter(c=>(txt(c.title)+' '+txt(c.teacher)).toLowerCase().includes(v.toLowerCase()));$('#course-list').innerHTML=list.map(courseCard).join('')||emptyState(t('No matching courses','没有匹配的课程'),t('Try a different keyword.','试试其他关键词。'))}
function formatDate(d){return new Date(d+'T12:00:00').toLocaleDateString(lang==='zh'?'zh-CN':'en-US',{month:'short',day:'numeric'})}function emptyState(a,b){return `<div class="empty">${icon('folder')}<h3>${a}</h3><p>${b}</p></div>`}
function statusBadge(s){let a={pending:[t('Not submitted','未提交'),'orange'],submitted:[t('Submitted','已提交'),'blue'],graded:[t('Graded','已评分'),'green']};let [text,color]=a[s]||a.pending;return `<span class="badge ${color}">${text}</span>`}
function assignmentsPage(){let list=db.assignments.filter(a=>a.type!=='quiz').filter(a=>assignmentTab==='all'||a.status===assignmentTab);return heading(t('Small steps. Meaningful work.','认真完成每一份成长。'),t('Stay on top of your coursework and feedback.','掌握作业进度，查看学习反馈。'),db.role==='teacher'?btn(t('New assignment','发布作业'),"newAssignment()",'primary','plus'):'')+`<div class="tabs">${[['all',t('All assignments','全部作业')],['pending',t('To do','待完成')],['submitted',t('Submitted','已提交')],['graded',t('Graded','已评分')]].map(([k,v])=>`<button class="${assignmentTab===k?'active':''}" onclick="assignmentTab='${k}';render()">${v}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>${t('ASSIGNMENT','作业')}</th><th>${t('DUE DATE','截止日期')}</th><th>${t('STATUS','状态')}</th><th>${t('SCORE','成绩')}</th><th></th></tr></thead><tbody>${list.map(a=>`<tr><td><strong>${esc(txt(a.title))}</strong><small>${esc(txt(course(a.course)?.title||''))}</small></td><td>${formatDate(a.due)}</td><td>${statusBadge(a.status)}</td><td>${a.score!==undefined?a.score+' / 100':'—'}</td><td>${btn(db.role==='teacher'?t('Review','评阅'):a.status==='pending'?t('Open assignment','查看作业'):t('View details','查看详情'),`openAssignment('${a.id}')`,'ghost')}</td></tr>`).join('')||`<tr><td colspan="5">${emptyState(t('You are all caught up','当前没有作业'),t('Assignments will appear here.','作业会显示在这里。'))}</td></tr>`}</tbody></table></div>`}

function projectsPage(){return heading(t('Great work happens together.','好项目，来自好协作。'),t('Team Horizon / SPM Learning Platform / Sprint 02','Horizon 小组 / SPM 智慧学习平台 / 第02轮迭代'),btn(t('Add task','添加任务'),"newTask()",'primary','plus'))+`<div class="toolbar" style="justify-content:space-between"><div class="members" style="margin-top:0"><span class="avatar">OL</span><span class="avatar blue">YW</span><span class="avatar green">MC</span><span class="avatar purple">JW</span><small>${t('4 members · Iterative & incremental','4名成员 · 迭代增量模型')}</small></div><span class="badge green">${t('ON TRACK','进展顺利')}</span></div><div class="tabs">${[['board',t('Task board','任务看板')],['scope',t('Project scope','项目范围')],['timeline',t('Milestones','里程碑')],['risks',t('Risk register','风险管理')],['report',t('Weekly report','项目周报')]].map(([k,l])=>`<button class="${projectTab===k?'active':''}" onclick="projectTab='${k}';render()">${l}</button>`).join('')}</div>${projectContent()}`}
function projectContent(){if(projectTab==='board')return `<div class="board">${[t('To do','待开始'),t('In progress','进行中'),t('Completed','已完成')].map((l,i)=>`<section class="board-column" ondragover="event.preventDefault()" ondrop="dropTask(event,${i})"><div class="board-title">${l}<span>${db.tasks.filter(a=>a.status===i).length}</span></div>${db.tasks.filter(a=>a.status===i).map(a=>`<article class="task" draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${a.id}')"><span class="badge ${{high:'orange',medium:'blue',low:'green'}[a.priority]}">${({high:t('High priority','高优先级'),medium:t('Medium priority','中优先级'),low:t('Low priority','低优先级')})[a.priority]}</span><h3>${esc(txt(a.title))}</h3><div class="task-meta"><span>${icon('calendar')}${formatDate(a.due)}</span><span class="avatar ${a.owner==='YW'?'blue':a.owner==='MC'?'green':'purple'}">${esc(a.owner)}</span></div><div class="task-actions"><button ${i===0?'disabled':''} onclick="moveTask('${a.id}',${i-1})">← ${t('Back','退回')}</button><button ${i===2?'disabled':''} onclick="moveTask('${a.id}',${i+1})">${i===1?t('Complete','完成'):t('Start task','开始')} →</button></div></article>`).join('')}<button class="small-link" onclick="newTask(${i})">${icon('plus')}${t('Add task','添加任务')}</button></section>`).join('')}</div>`;if(projectTab==='scope')return `<div class="panel wide-panel"><div class="section-heading"><h2>${t('Project scope plan','项目范围计划')}</h2><span class="badge green">${t('ITERATION 01','第01轮迭代')}</span></div><p class="muted">${t('Keep the first release focused, clear and achievable.','让首个版本保持专注、清晰、可实现。')}</p><form onsubmit="saveScope(event)"><div class="field"><label for="scope-text">${t('Goals, deliverables and boundaries','目标、交付成果与范围边界')}</label><textarea id="scope-text" name="scope" style="min-height:230px">${esc(txt(db.scope))}</textarea></div><div class="notice">${t('For the first weekly report, a WBS is not required. Focus on scope, responsibilities and next steps.','本次周报不要求提交WBS。请聚焦项目范围、职责分工及下一步计划。')}</div><div class="modal-actions">${btn(t('Download scope plan','下载范围计划'),"downloadScope()",'outline','download')}<button class="btn primary" type="submit">${t('Save scope','保存范围')}</button></div></form></div>`;if(projectTab==='timeline')return `<div class="panel wide-panel"><div class="section-heading"><h2>${t('One milestone at a time.','一步一个里程碑。')}</h2></div>${[[t('Team formation','组建团队'),'2026-11-02',true],[t('Scope plan & first weekly report','范围计划与首次周报'),'2026-11-08',false],[t('Core platform prototype','基础平台原型'),'2026-11-15',false],[t('Assessment & collaboration workflows','测评与协作流程'),'2026-11-22',false],[t('Final review & demonstration','最终评审与演示'),'2026-11-29',false]].map(([l,d,done],i)=>`<div class="event-row ${i%2?'purple':''}" style="padding:20px;margin:0;border-bottom:1px solid var(--line)"><span class="stat-icon">${icon(done?'check':'flag')}</span><div><strong style="font-size:13px">${l}</strong><small>${formatDate(d)}</small></div><span style="margin-left:auto" class="badge ${done?'green':i===1?'blue':'purple'}">${done?t('Completed','已完成'):i===1?t('Next milestone','下个里程碑'):t('Planned','已计划')}</span></div>`).join('')}</div>`;if(projectTab==='risks')return `<div class="section-heading"><h2>${t('Plan for the unexpected.','为不确定性做好准备。')}</h2>${btn(t('Add risk','添加风险'),"newRisk()",'outline','plus')}</div><div class="table-wrap"><table><thead><tr><th>${t('RISK','风险')}</th><th>${t('PROBABILITY','概率')}</th><th>${t('IMPACT','影响')}</th><th>${t('MITIGATION','应对措施')}</th></tr></thead><tbody>${db.risks.map(r=>`<tr><td><strong>${esc(txt(r.title))}</strong></td><td>${riskLabel(r.probability)}</td><td><span class="badge orange">${riskLabel(r.impact)}</span></td><td>${esc(txt(r.mitigation))}</td></tr>`).join('')}</tbody></table></div>`;return `<div class="split"><div class="panel wide-panel"><span class="badge blue">${t('WEEK 06','第六周')}</span><h2>${t('A clear record of your progress.','清晰记录每一步进展。')}</h2><p class="muted">${t('Bring your meeting notes, decisions and next steps into one report.','把会议纪要、决策与后续计划整合成一份规范周报。')}</p><form onsubmit="saveReport(event)"><div class="form-grid"><div class="field"><label>${t('Meeting date','会议日期')}</label><input type="date" name="date" value="${esc(db.report?.date||'2026-11-04')}" required></div><div class="field"><label>${t('Participants','参会人员')}</label><input name="participants" required value="${esc(db.report?.participants||'Olia, Yichen, Ming, Jiawen')}"></div></div>${[['progress',t('Progress & completed work','进展与已完成工作')],['decisions',t('Discussion & decisions','讨论内容与决策')],['next',t('Next steps & responsibilities','下一步计划与责任分工')]].map(([k,l])=>`<div class="field"><label>${l}</label><textarea name="${k}" required placeholder="${t('Write a clear, concise update...','请简明记录…')}">${esc(db.report?.[k]||'')}</textarea></div>`).join('')}<div class="modal-actions"><button class="btn primary" type="submit">${t('Save weekly report','保存项目周报')}</button></div></form></div><div class="panel wide-panel" style="align-self:start"><h3>${t('Ready to share','准备分享')}</h3><p class="muted">${t('Save your report, then download an editable Markdown copy or print it to PDF using your browser.','保存后可下载可编辑的Markdown文件，或使用浏览器打印为PDF。')}</p><div style="display:flex;gap:10px;flex-wrap:wrap">${btn(t('Download report','下载周报'),"exportReport()",'outline','download')}${btn(t('Print / Save PDF','打印 / 保存PDF'),"printReport()",'ghost','file')}</div><div class="notice" style="font-size:11px">${t('Include meeting date, participants, discussion, decisions and the next action plan. No WBS is required for the first report.','请包含会议日期、参会人员、讨论、决策和行动计划。首次周报无需WBS。')}</div></div></div>`}
function riskLabel(s){return ({High:t('High','高'),Medium:t('Medium','中'),Low:t('Low','低')})[s]||esc(s)}
function moveTask(id,status){if(status<0||status>2)return;db.tasks.find(a=>a.id===id).status=status;save();render();toast('Task updated','任务已更新')}function dropTask(e,status){e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(db.tasks.some(a=>a.id===id))moveTask(id,status)}
function saveScope(e){e.preventDefault();const value=new FormData(e.target).get('scope');db.scope=[value,value];save();toast('Project scope saved','项目范围已保存')}
function miniCalendar(){const date=new Date(2026,10+calendarOffset,1),month=date.getMonth(),year=date.getFullYear(),start=(date.getDay()+6)%7,days=new Date(year,month+1,0).getDate();const name=date.toLocaleDateString(lang==='zh'?'zh-CN':'en-US',{month:'long',year:'numeric'});return `<div class="calendar-header"><span>${name}</span><div><button onclick="calendarOffset--;render()" aria-label="${t('Previous month','上个月')}">${icon('left')}</button><button onclick="calendarOffset++;render()" aria-label="${t('Next month','下个月')}">${icon('chevron')}</button></div></div><div class="calendar-grid">${t(['M','T','W','T','F','S','S'],['一','二','三','四','五','六','日']).map(d=>`<span class="dayname">${d}</span>`).join('')}${Array.from({length:Math.ceil((start+days)/7)*7},(_,i)=>{let n=i-start+1;const valid=n>0&&n<=days;return `<button ${!valid?'disabled':''} class="${!valid?'faint':n===selectedDay&&month===10?'today':''} ${valid&&[4,6,8,10,15,22].includes(n)&&month===10?'event':''}" onclick="selectCalendarDay(${n})">${n<1?new Date(year,month,0).getDate()+n:n>days?n-days:n}</button>`}).join('')}</div>`}
function selectCalendarDay(n){selectedDay=n;if(page!=='calendar'){page='calendar'}render()}
function calendarPage(){return heading(t('Make room for what matters.','为重要的事安排时间。'),t('Your learning, deadlines and team moments in one place.','课程、截止日期与团队日程，一目了然。'))+`<div class="split"><div class="panel wide-panel">${miniCalendar()}</div><div class="panel wide-panel"><div class="section-heading"><h2>${t('Upcoming this month','本月即将到来')}</h2></div>${db.assignments.filter(a=>a.status==='pending').map(a=>`<button class="deadline" style="text-align:left;width:100%" onclick="openAssignment('${a.id}')"><span class="deadline-icon">${icon('calendar')}</span><div><strong>${esc(txt(a.title))}</strong><p>${formatDate(a.due)} · ${t('Course deadline','课程截止日期')}</p>${statusBadge(a.status)}</div></button>`).join('')}<div class="notice">${t('Selected day: ','已选日期：')}${new Date(2026,10+calendarOffset,selectedDay).toLocaleDateString(lang==='zh'?'zh-CN':'en-US')}. ${t('Course deadlines are listed above.','课程截止日期见上方。')}</div></div></div>`}
const resources=[{id:'scope',title:['Project scope template','项目范围计划模板'],type:'MD',description:['Goals, deliverables, boundaries and acceptance criteria.','目标、交付成果、边界与验收标准。']},{id:'weekly',title:['Weekly report template','项目周报模板'],type:'MD',description:['Meeting notes, decisions, progress and next steps.','会议纪要、决策、进度与下一步计划。']},{id:'risk',title:['Risk register template','风险登记册模板'],type:'CSV',description:['Identify, assess and manage project risks.','识别、评估与管理项目风险。']},{id:'scrum',title:['Sprint retrospective guide','迭代回顾指南'],type:'MD',description:['Reflect together. Find one thing to improve.','共同回顾，找到一个值得改进的地方。']},{id:'models',title:['Software process model notes','软件过程模型学习笔记'],type:'MD',description:['A practical overview of common development models.','常用开发模型的实用概览。']},{id:'change',title:['Change request template','变更申请模板'],type:'MD',description:['Describe a change and assess its project impact.','描述变更并评估对项目的影响。']}];
function resourcesPage(){return heading(t('Good ideas need good tools.','好工具，让好想法更进一步。'),t('Practical templates for your next project milestone.','为下一个项目里程碑准备的实用模板。'))+`<div class="resource-grid">${resources.map(r=>`<article class="panel resource-card"><span class="resource-type">${r.type}</span><h3>${txt(r.title)}</h3><p>${txt(r.description)}</p>${btn(t('Download template','下载模板'),`downloadResource('${r.id}')`,'outline','download')}</article>`).join('')}</div>`}
function gradesPage(){return heading(db.role==='teacher'?t('Feedback that moves learning forward.','用反馈促进学习成长。'):t('See how far you have come.','看见自己的每一步成长。'),t('Scores, meaningful feedback and room to grow.','成绩、有效反馈，以及继续成长的空间。'),db.role==='teacher'?btn(t('Export gradebook','导出成绩册'),"exportGrades()",'outline','download'):'')+`<div class="stats" style="grid-template-columns:repeat(3,1fr)"><div class="stat"><div class="stat-label">${t('Assignment average','作业平均成绩')}</div><div class="stat-value">${Math.round(db.assignments.filter(a=>a.score!==undefined).reduce((n,a)=>n+a.score,0)/Math.max(1,db.assignments.filter(a=>a.score!==undefined).length))}<small> / 100</small></div></div><div class="stat"><div class="stat-label">${t('Assessments completed','已完成测评')}</div><div class="stat-value">${db.assignments.filter(a=>a.score!==undefined).length}</div></div><div class="stat"><div class="stat-label">${t('Practice quiz','练习测验')}</div><div class="stat-value">${db.quizScore!==undefined?db.quizScore+'%':'—'}</div></div></div><div class="table-wrap"><table><thead><tr><th>${t('ASSESSMENT','测评')}</th><th>${t('STATUS','状态')}</th><th>${t('SCORE','成绩')}</th><th>${t('INSTRUCTOR FEEDBACK','教师反馈')}</th>${db.role==='teacher'?'<th></th>':''}</tr></thead><tbody>${db.assignments.map(a=>`<tr><td><strong>${esc(txt(a.title))}</strong><small>${esc(txt(course(a.course)?.title||''))}</small></td><td>${statusBadge(a.status)}</td><td>${a.score!==undefined?'<strong>'+a.score+'</strong> / 100':'—'}</td><td style="max-width:400px;font-size:11px;color:var(--muted)">${a.feedback?esc(txt(a.feedback)):t('Feedback will appear after review.','评阅后显示反馈。')}</td>${db.role==='teacher'?`<td>${btn(t('Grade','评分'),`openAssignment('${a.id}')`,'ghost')}</td>`:''}</tr>`).join('')}</tbody></table></div>`}
function discussionsPage(){return heading(t('Better questions. Shared understanding.','交流好问题，共享新理解。'),t('A space to ask, share and learn from each other.','提问、分享、互相学习的空间。'),btn(t('Start a discussion','发起讨论'),"newPost()",'primary','plus'))+`<div style="max-width:900px">${db.posts.map(p=>`<article class="panel post"><div class="post-heading"><span class="avatar ${p.id==='p2'?'blue':''}">${esc(p.initials)}</span><div><strong>${esc(p.author)}</strong><small>${t('Project Management and Process Improvement · Course discussion','项目管理与过程改进 · 课程讨论')}</small></div>${p.id==='p2'?`<span class="badge blue" style="margin-left:auto">${t('COURSE NOTICE','课程公告')}</span>`:''}</div><h3>${esc(txt(p.title))}</h3><p>${esc(txt(p.body))}</p>${p.replies.map(r=>`<div class="notice"><strong>${esc(r.author)}</strong><br>${esc(r.body)}</div>`).join('')}<div class="post-actions"><button class="${p.liked?'liked':''}" onclick="likePost('${p.id}')">${icon('heart')}${p.likes} ${t('helpful','有帮助')}</button><button onclick="replyPost('${p.id}')">${icon('chat')}${p.replies.length} ${t('replies','条回复')}</button></div></article>`).join('')}</div>`}
function analyticsPage(){return heading(t('Progress you can see.','让进步清晰可见。'),t('A thoughtful look at your learning journey. Demo metrics are illustrative.','回顾学习旅程。此处的统计为演示数据。'))+statCards()+`<div class="split"><div class="panel wide-panel"><div class="section-heading"><h2>${t('Learning activity','学习活跃度')}</h2><span class="badge blue">${t('ILLUSTRATIVE','示例数据')}</span></div><p class="muted" style="font-size:11px">${t('Hours of focused learning · last 7 days','过去7天的专注学习时长')}</p><div class="chart">${[1.2,2,1.5,3,2.5,1.7,.6].map((v,i)=>`<div class="bar-wrap"><div class="bar" style="height:${v*40}px"><span>${v}h</span></div><span>${t(['M','T','W','T','F','S','S'],['一','二','三','四','五','六','日'])[i]}</span></div>`).join('')}</div></div><div class="panel wide-panel"><div class="section-heading"><h2>${t('Course completion','课程完成情况')}</h2></div>${db.courses.filter(c=>db.enrolled.includes(c.id)).map(c=>`<div class="progress-meta" style="font-size:11px"><span>${esc(txt(c.title))}</span><strong>${progress(c)}%</strong></div><div class="progress-track" style="height:6px;margin-bottom:22px"><span style="width:${progress(c)}%"></span></div>`).join('')}</div></div>`}

function profilePage(){return heading(t('Make this space yours.','打造属于你的学习空间。'),t('A few small details for a better learning day.','一点个性化设置，让学习体验更好。'))+`<div class="split"><section class="panel wide-panel"><div class="profile-card"><span class="avatar">${esc(db.user.name.slice(0,2).toUpperCase())}</span><div><h3>${esc(db.user.name)}</h3><p>${roleName()} · ${t('Demo workspace','演示空间')}</p></div></div><dl class="identity-details"><dt>${t('Full name','姓名')}</dt><dd>${esc(db.user.name)}</dd><dt>${t('ID ending','编号尾号')}</dt><dd>${db.user.maskedId}</dd><dt>${t('Role','角色')}</dt><dd>${roleName()}</dd></dl></section><div class="panel wide-panel" style="align-self:start"><h3>${t('Preferences','偏好设置')}</h3><div class="field"><label>${t('Interface language','界面语言')}</label><select onchange="switchLanguage()"><option ${lang==='en'?'selected':''}>English</option><option ${lang==='zh'?'selected':''}>简体中文</option></select></div><div class="field"><label>${t('Appearance','外观')}</label><select onchange="db.theme=this.value;save();render()"><option value="light" ${db.theme==='light'?'selected':''}>${t('Light','浅色')}</option><option value="dark" ${db.theme==='dark'?'selected':''}>${t('Dark','深色')}</option></select></div><div class="form-note">${t('User accounts and sign-in details are shared across the site. Learning activity and preferences are saved in this browser.','用户账户与登录信息由全站共享。学习记录与偏好设置保存在当前浏览器。')}</div></div></div>`}
function modal(title,intro,body,wide=false){$('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-heading"><h2>${title}</h2><button class="icon-button" onclick="closeModal()" aria-label="${t('Close dialog','关闭对话框')}">${icon('close')}</button></div>${intro?`<p class="modal-intro">${intro}</p>`:''}${body}</section></div>`;wireLabels();document.body.style.overflow='hidden';setTimeout(()=>$('.modal input:not([type=radio]),.modal textarea,.modal button')?.focus(),50)}function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow=''}

function accountMenu() {
  modal(t('Your account', '我的账户'), '', `
    <div class="profile-card">
      <span class="avatar">${esc(db.user.name.split(' ').map(part => part[0]).slice(0, 2).join(''))}</span>
      <div><h3>${esc(db.user.name)}</h3><p>${roleName()} · ${db.user.maskedId}</p></div>
    </div>
    <div class="modal-actions">
      ${btn(t('Sign out','退出登录'), 'signOut()', 'outline', 'logout')}
      ${btn(t('Profile & settings','个人资料与设置'), "closeModal();go('profile')", 'primary')}
    </div>`);
}

function renderAuth() {
  const signingIn = authMode === 'signin';
  $('#app').innerHTML = `<main class="auth-shell">
    <header class="auth-header">
      <div class="brand"><span class="brand-logo">${icon('logo')}</span>
        <div><strong>spm<span style="font-weight:500">studio</span></strong><small>LEARN. BUILD. GROW.</small></div>
      </div>
      <button type="button" class="lang-button" onclick="switchLanguage()" aria-label="${t('Switch to Chinese','切换至英文')}">${icon('globe')}${t('EN','中文')}</button>
    </header>
    <div class="auth-layout">
      <section class="auth-intro">
        <span class="eyebrow">${t('SPM STUDIO · CLASS WORKSPACE','SPM STUDIO · 班级学习空间')}</span>
        <h1>${t('Learn with purpose.<br>Build with confidence.', '学有所向。<br>行有所成。')}</h1>
        <p>${t('Your courses, assignments and team projects in one place.','在同一空间管理课程、作业和小组项目。')}</p>
        <div class="auth-roles">${['student','teacher','admin'].map(role => `<span>${roleLabel(role)}</span>`).join('')}</div>
      </section>
      <section class="auth-card" aria-labelledby="auth-title">
        <div class="auth-tabs">
          <button type="button" aria-pressed="${!signingIn}" onclick="showAuth('register')">${t('Register','注册')}</button>
          <button type="button" aria-pressed="${signingIn}" onclick="showAuth('signin')">${t('Sign in','登录')}</button>
        </div>
        <h2 id="auth-title">${signingIn ? t('Welcome back', '欢迎回来') : t('Create your profile', '创建账户')}</h2>
        <p>${t('Enter your full name and ID as listed on the class roster.','请输入班级名册中的完整姓名和编号。')}</p>
        <form onsubmit="submitRosterForm(event)">
          <div class="field"><label for="roster-name">${t('Full name','完整姓名')}</label>
            <input id="roster-name" name="name" maxlength="80" autocomplete="name" required></div>
          <div class="field"><label for="roster-id">${t('Student, teacher or administrator ID','学号、教师编号或管理员编号')}</label>
            <div class="id-field">
              <input id="roster-id" name="id" type="password" maxlength="24" autocomplete="off" autocapitalize="characters" spellcheck="false" required>
              <button type="button" class="icon-button id-visibility" onclick="toggleRosterId(this)" aria-controls="roster-id" aria-label="${t('Show ID','显示编号')}" title="${t('Show ID','显示编号')}">${icon('eye')}</button>
            </div>
          </div>
          <p id="roster-error" class="auth-error" role="alert" hidden></p>
          <button class="btn primary" type="submit">${signingIn ? t('Sign in','登录') : t('Register','注册')}${icon('arrow')}</button>
        </form>
        <p class="form-note">${t('Roster members already have demo profiles. Use Sign in with your name and ID.','名册成员已开通演示账户，请使用姓名和编号登录。')}</p>
      </section>
    </div>
  </main>`;
}

function showAuth(mode) {
  authMode = mode;
  render();
  $('#roster-name').focus();
}

function toggleRosterId(button) {
  const input = $('#roster-id');
  const reveal = input.type === 'password';
  input.type = reveal ? 'text' : 'password';
  const label = reveal ? t('Hide ID','隐藏编号') : t('Show ID','显示编号');
  button.setAttribute('aria-label', label);
  button.title = label;
  button.innerHTML = icon(reveal ? 'eyeOff' : 'eye');
}

function approveTeacher(id,approved){if(db.role!=='admin')return;let a=db.accounts.find(x=>x.id===id);a.pending=false;a.rejected=!approved;db.audit.unshift({name:a.name,approved,time:new Date().toISOString()});save();render();toast(approved?'Teacher application approved':'Teacher application rejected',approved?'教师申请已通过':'教师申请已拒绝')}
function createCourse(){if(db.role!=='teacher')return;modal(t('Create something worth learning.','创建值得学习的课程。'),t('Start with a clear goal. New courses are saved as drafts.','从明确的目标开始。新课程默认保存为草稿。'),`<form onsubmit="saveNewCourse(event)"><div class="field"><label>${t('Course title · English','课程名称 · 英文')}</label><input name="en" required maxlength="100"></div><div class="field"><label>${t('Course title · Chinese','课程名称 · 中文')}</label><input name="zh" required maxlength="100"></div><div class="field"><label>${t('Course description','课程介绍')}</label><textarea name="description" required></textarea></div><div class="form-grid"><div class="field"><label>${t('Number of sample lessons','示例课时数')}</label><input type="number" name="chapters" min="1" max="12" value="6" required></div><div class="field"><label>${t('Cover color','封面颜色')}</label><select name="color"><option value="sky">${t('Sky blue','天空蓝')}</option><option value="lavender">${t('Lavender','薰衣草紫')}</option><option value="mint">${t('Mint','薄荷绿')}</option><option value="peach">${t('Peach','蜜桃色')}</option></select></div></div><div class="modal-actions"><button class="btn primary" type="submit">${t('Save draft','保存草稿')}</button></div></form>`)}function saveNewCourse(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));db.courses.push({id:uid('c'),title:[d.en,d.zh],category:['Project management','项目管理'],teacher:[db.user.name,db.user.name],code:'SPM '+(db.courses.length+301),color:d.color,chapters:Number(d.chapters),description:[d.description,d.description],draft:true});save();closeModal();go('courses');toast('Course draft created','课程草稿已创建')}function publishCourse(id){if(!canEditLessons())return;course(id).draft=false;save();closeModal();render();toast('Course published to the catalog','课程已发布到课程中心')}
function openAssignment(id){let a=db.assignments.find(x=>x.id===id);if(a.type==='quiz'){openQuiz();return}const teacher=db.role==='teacher';modal(esc(txt(a.title)),esc(txt(course(a.course)?.title||'')),`<div class="toolbar"><span class="date-pill">${icon('calendar')}${t('Due','截止')} ${formatDate(a.due)}</span>${statusBadge(a.status)}</div><div class="notice">${a.type==='report'?t('Summarize your meeting, completed work, key decisions and the next action plan. A WBS is not required for the first report.','总结会议内容、已完成工作、关键决策及下一步计划。首次周报无需WBS。'):t('Define the project goal, deliverables, boundaries, responsibilities and acceptance criteria. Keep the first iteration achievable.','明确项目目标、交付成果、边界、职责与验收标准，让首轮迭代保持可实现。')}</div>${a.submission?`<h4>${t('Submitted work','已提交内容')}</h4><div class="report-content">${esc(a.submission)}</div>${a.filename?`<p class="muted" style="font-size:11px">${t('File reference (name only):','文件记录（仅文件名）：')} ${esc(a.filename)}</p>`:''}`:''}${a.feedback?`<h4>${t('Teacher feedback','教师反馈')} · ${a.score}/100</h4><p class="muted">${esc(txt(a.feedback))}</p>`:''}${teacher?`<form onsubmit="gradeAssignment(event,'${id}')"><div class="field"><label>${t('Score out of 100','分数（满分100）')}</label><input type="number" name="score" min="0" max="100" value="${a.score??''}" required></div><div class="field"><label>${t('Feedback','反馈')}</label><textarea name="feedback" required>${esc(a.feedback?txt(a.feedback):'')}</textarea></div><div class="form-note">${t('This demo grades the shared sample submission. Real students need separate authenticated records.','本演示评阅共用示例作业。真实学生需使用独立身份与数据记录。')}</div><div class="modal-actions"><button type="submit" class="btn primary">${t('Publish grade','发布成绩')}</button></div></form>`:a.status!=='graded'?`<form onsubmit="submitAssignment(event,'${id}')"><div class="field"><label>${t('Your answer / submission notes','你的答案 / 提交说明')}</label><textarea name="submission" required minlength="10" placeholder="${t('Write at least 10 characters about your work...','请至少输入10个字符，描述你的成果…')}">${esc(a.submission||'')}</textarea></div><div class="field"><label>${t('Optional file reference','可选文件记录')}</label><input type="file" name="file" accept=".pdf,.docx,.md,.txt,.pptx"><small class="muted" style="font-size:10px">${t('Demo: only the file name is saved. File contents are not uploaded.','演示：仅保存文件名，不上传文件内容。')}</small></div><div class="modal-actions">${a.type==='report'?btn(t('Use report builder','使用周报工具'),"closeModal();projectTab='report';go('projects')",'outline'):''}<button class="btn primary" type="submit">${t(a.status==='submitted'?'Resubmit work':'Submit assignment',a.status==='submitted'?'重新提交':'提交作业')}</button></div></form>`:''}`)}
function submitAssignment(e,id){e.preventDefault();const d=new FormData(e.target),a=db.assignments.find(x=>x.id===id);a.submission=d.get('submission');a.filename=d.get('file')?.name||a.filename||'';a.status='submitted';a.submittedAt=new Date().toISOString();save();closeModal();render();toast('Assignment submitted in your demo workspace','作业已提交到演示空间')}
function gradeAssignment(e,id){e.preventDefault();if(db.role!=='teacher')return;const d=new FormData(e.target),a=db.assignments.find(x=>x.id===id);a.score=Number(d.get('score'));a.feedback=[d.get('feedback'),d.get('feedback')];a.status='graded';save();closeModal();render();toast('Grade and feedback published','成绩与反馈已发布')}
function newAssignment(){if(db.role!=='teacher')return;modal(t('A meaningful next step.','布置一次有意义的实践。'),t('Create an assignment for your learners.','为学习者创建作业。'),`<form onsubmit="saveNewAssignment(event)"><div class="field"><label>${t('Assignment title','作业名称')}</label><input name="title" required maxlength="120"></div><div class="field"><label>${t('Course','课程')}</label><select name="course">${db.courses.map(c=>`<option value="${c.id}">${esc(txt(c.title))}</option>`).join('')}</select></div><div class="field"><label>${t('Due date','截止日期')}</label><input type="date" name="due" min="2026-11-04" required></div><div class="modal-actions"><button class="btn primary" type="submit">${t('Publish assignment','发布作业')}</button></div></form>`)}function saveNewAssignment(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));db.assignments.push({id:uid('a'),title:[d.title,d.title],course:d.course,due:d.due,type:'assignment',status:'pending'});save();closeModal();render();toast('Assignment published','作业已发布')}
const quiz=[{q:['Which model delivers a usable product in successive parts?','哪种模型通过连续的部分交付可用产品？'],options:[['Waterfall','瀑布模型'],['Incremental','增量模型'],['Big bang','大爆炸模型']],answer:1,explain:['Incremental development delivers usable functionality in successive releases.','增量开发通过连续版本逐步交付可用功能。']},{q:['A stakeholder requests a large feature outside the agreed scope. What should the team do first?','干系人提出范围外的大功能需求，团队首先应做什么？'],options:[['Build it immediately','立即开发'],['Ignore the request','忽略请求'],['Record and assess the change','记录并评估变更']],answer:2,explain:['Record the request, assess schedule and resource impact, then seek an agreed decision.','记录请求、评估进度与资源影响，再共同决策。']},{q:['What is the purpose of a retrospective?','回顾会议的目的是什么？'],options:[['Find improvements for the next iteration','为下次迭代寻找改进点'],['Assign blame','追究责任'],['Replace all planning','替代全部计划']],answer:0,explain:['A retrospective helps the team inspect its process and choose actionable improvements.','回顾帮助团队检查过程并选择可执行的改进措施。']}];
function openQuiz(){modal(t('A little practice goes a long way.','用练习巩固每一点知识。'),t('Three questions · no time limit · answers stay here until you submit.','三道题 · 不限时 · 提交前答案保留在本窗口。'),`<form onsubmit="submitQuiz(event)">${quiz.map((q,i)=>`<fieldset style="border:0;padding:0;margin:22px 0"><legend style="font-size:13px;font-weight:650">${i+1}. ${txt(q.q)}</legend>${q.options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" required>${txt(o)}</label>`).join('')}</fieldset>`).join('')}<div class="modal-actions"><button class="btn primary" type="submit">${t('Submit answers','提交答案')}</button></div></form>`,true)}
function submitQuiz(e){e.preventDefault();const d=new FormData(e.target);let score=quiz.filter((q,i)=>Number(d.get('q'+i))===q.answer).length;db.quizScore=Math.round(score/quiz.length*100);let a=db.assignments.find(a=>a.type==='quiz');if(a){a.score=db.quizScore;a.status='graded';a.feedback=[`${score} / ${quiz.length} correct.`,`${score} / ${quiz.length} 题正确。`]}save();render();modal(t('Every attempt is progress.','每一次尝试，都是进步。'),t('Here is what to take into your next project.','把学到的知识带到下一个项目中。'),`<div class="metric-large" style="text-align:center;color:var(--blue);margin:20px">${db.quizScore}%</div>${quiz.map((q,i)=>`<div class="notice" style="border-color:${Number(d.get('q'+i))===q.answer?'#4fa88b':'#d5a168'}"><strong>${i+1}. ${txt(q.q)}</strong><p>${t('Correct answer:','正确答案：')} ${txt(q.options[q.answer])}</p><span>${txt(q.explain)}</span></div>`).join('')}<div class="modal-actions">${btn(t('Back to workspace','返回工作空间'),"closeModal()",'primary')}</div>`,true)}
function newTask(status=0){modal(t('One clear next action.','明确下一步行动。'),t('Give the task an owner and a realistic deadline.','为任务指定负责人和合理的截止日期。'),`<form onsubmit="saveTask(event,${status})"><div class="field"><label>${t('Task name','任务名称')}</label><input name="title" required maxlength="120"></div><div class="form-grid"><div class="field"><label>${t('Assignee','负责人')}</label><select name="owner"><option value="OL">Olia</option><option value="YW">Yichen Wang</option><option value="MC">Ming Chen</option><option value="JW">Jiawen</option></select></div><div class="field"><label>${t('Priority','优先级')}</label><select name="priority"><option value="medium">${t('Medium','中')}</option><option value="high">${t('High','高')}</option><option value="low">${t('Low','低')}</option></select></div></div><div class="field"><label>${t('Deadline','截止日期')}</label><input type="date" name="due" value="2026-11-08" required></div><div class="modal-actions"><button class="btn primary" type="submit">${t('Add task','添加任务')}</button></div></form>`)}function saveTask(e,status){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));db.tasks.push({id:uid('t'),title:[d.title,d.title],status,owner:d.owner,priority:d.priority,due:d.due});save();closeModal();render();toast('Task added to the board','任务已加入看板')}
function newRisk(){modal(t('Name it. Plan for it.','识别风险，提前应对。'),t('A visible risk is easier to manage.','可见的风险更容易管理。'),`<form onsubmit="saveRisk(event)"><div class="field"><label>${t('Risk description','风险描述')}</label><input name="title" required maxlength="160"></div><div class="form-grid">${[['probability',t('Probability','发生概率')],['impact',t('Impact','影响程度')]].map(([n,l])=>`<div class="field"><label>${l}</label><select name="${n}"><option value="Medium">${t('Medium','中')}</option><option value="High">${t('High','高')}</option><option value="Low">${t('Low','低')}</option></select></div>`).join('')}</div><div class="field"><label>${t('Mitigation plan','应对计划')}</label><textarea name="mitigation" required></textarea></div><div class="modal-actions"><button class="btn primary" type="submit">${t('Save risk','保存风险')}</button></div></form>`)}function saveRisk(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));db.risks.push({id:uid('r'),title:[d.title,d.title],probability:d.probability,impact:d.impact,mitigation:[d.mitigation,d.mitigation]});save();closeModal();render();toast('Risk added to the register','风险已登记')}
function saveReport(e){e.preventDefault();db.report=Object.fromEntries(new FormData(e.target));save();toast('Weekly report saved. Ready to download.','项目周报已保存，可下载。')}
function reportText(){if(!db.report)return '';const r=db.report;return `# ${t('Team Horizon — Weekly Progress Report','Horizon小组 — 项目周报')}\n\n${t('Project: SPM Learning Platform','项目：SPM智慧学习平台')}\n${t('Meeting date','会议日期')}: ${r.date}\n${t('Participants','参会人员')}: ${r.participants}\n\n## ${t('Progress & completed work','进展与已完成工作')}\n${r.progress}\n\n## ${t('Discussion & decisions','讨论内容与决策')}\n${r.decisions}\n\n## ${t('Next steps & responsibilities','下一步计划与责任分工')}\n${r.next}\n`}
function download(name,content,mime='text/markdown;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+content],{type:mime}));a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function exportReport(){if(!db.report){toast('Save your report first','请先保存周报');return}download('SPM-Weekly-Report-'+db.report.date+'.md',reportText());toast('Weekly report downloaded','项目周报已下载')}function printReport(){if(!db.report){toast('Save your report first','请先保存周报');return}const w=window.open('','_blank');if(!w){toast('Please allow the print window to open.','请允许打开打印窗口。');return}w.document.write(`<html><head><title>SPM Weekly Report</title><style>body{font:14px/1.8 sans-serif;max-width:760px;margin:60px auto;padding:20px;color:#243553}pre{font:inherit;white-space:pre-wrap}</style></head><body><pre>${esc(reportText().replace(/^##? /gm,''))}</pre></body></html>`);w.document.close();w.print()}
function downloadScope(){download('SPM-Project-Scope.md','# '+t('Project Scope Plan','项目范围计划')+'\n\n'+txt(db.scope));toast('Scope plan downloaded','范围计划已下载')}
function downloadResource(id){let r=resources.find(x=>x.id===id),body;if(id==='risk'){body=t('Risk,Probability,Impact,Owner,Mitigation,Status\nScope growth,Medium,High,Team,Review all scope changes,Open','风险,概率,影响,负责人,应对措施,状态\n范围扩大,中,高,小组,评审所有范围变更,待处理');download('SPM-Risk-Register.csv',body,'text/csv;charset=utf-8')}else{const templates={scope:t('## Project goal\n\n## Deliverables\n\n## In scope\n\n## Out of scope\n\n## Acceptance criteria\n\n## Roles and responsibilities','## 项目目标\n\n## 交付成果\n\n## 范围内\n\n## 范围外\n\n## 验收标准\n\n## 职责分工'),weekly:t('Meeting date:\nParticipants:\n\n## Completed work\n\n## Discussion & decisions\n\n## Next steps & owners\n\nNote: WBS is not required for the first report.','会议日期：\n参会人员：\n\n## 已完成工作\n\n## 讨论与决策\n\n## 下一步计划与负责人\n\n注：首次周报不要求WBS。'),scrum:t('## What went well?\n\n## What could improve?\n\n## One action for the next sprint\n\nOwner:\nDue date:','## 哪些做得好？\n\n## 哪些需要改进？\n\n## 下次迭代的一项行动\n\n负责人：\n截止日期：'),models:t('## Waterfall\nSequential phases with planned handoffs.\n\n## Iterative\nRefine the solution through repeated cycles.\n\n## Incremental\nDeliver usable functionality in successive parts.\n\n## Agile\nAdapt through short feedback cycles and collaboration.','## 瀑布模型\n按顺序推进阶段，明确阶段交接。\n\n## 迭代模型\n通过反复循环优化解决方案。\n\n## 增量模型\n逐步交付可用功能。\n\n## 敏捷\n通过短周期反馈与协作适应变化。'),change:t('## Requested change\n\n## Reason\n\n## Impact on scope, schedule and resources\n\n## Alternatives\n\n## Decision & approver','## 申请变更\n\n## 变更原因\n\n## 对范围、进度和资源的影响\n\n## 替代方案\n\n## 决策与审批人')};download('SPM-'+id+'-Template.md','# '+txt(r.title)+'\n\n'+templates[id])}toast('Template downloaded','模板已下载')}
function exportGrades(){const cell=s=>'"'+String(s).replace(/"/g,'""')+'"';download('SPM-Gradebook.csv',[['Assignment','Course','Status','Score','Feedback'],...db.assignments.map(a=>[txt(a.title),txt(course(a.course)?.title||''),a.status,a.score??'',a.feedback?txt(a.feedback):''])].map(r=>r.map(cell).join(',')).join('\n'),'text/csv;charset=utf-8');toast('Gradebook exported','成绩册已导出')}
function newPost(){modal(t('Start a good conversation.','开启一次有价值的交流。'),t('Share a question, an insight or something your team learned.','分享问题、想法或团队的新发现。'),`<form onsubmit="savePost(event)"><div class="field"><label>${t('Title','标题')}</label><input name="title" required maxlength="150"></div><div class="field"><label>${t('Your message','内容')}</label><textarea name="body" required minlength="10"></textarea></div><div class="modal-actions"><button class="btn primary" type="submit">${t('Post discussion','发布讨论')}</button></div></form>`)}function savePost(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));db.posts.unshift({id:uid('p'),author:db.user.name,initials:db.user.name.split(' ').map(x=>x[0]).slice(0,2).join(''),title:[d.title,d.title],body:[d.body,d.body],likes:0,liked:false,replies:[]});save();closeModal();render();toast('Discussion posted','讨论已发布')}function likePost(id){let p=db.posts.find(x=>x.id===id);p.liked=!p.liked;p.likes+=p.liked?1:-1;save();render()}function replyPost(id){modal(t('Add to the conversation.','分享你的见解。'),t('A useful reply can make someone’s day.','一条有帮助的回复，可能让别人豁然开朗。'),`<form onsubmit="saveReply(event,'${id}')"><div class="field"><label>${t('Your reply','你的回复')}</label><textarea name="reply" required></textarea></div><div class="modal-actions"><button class="btn primary" type="submit">${t('Post reply','发布回复')}</button></div></form>`)}function saveReply(e,id){e.preventDefault();db.posts.find(x=>x.id===id).replies.push({author:db.user.name,body:new FormData(e.target).get('reply')});save();closeModal();render();toast('Reply posted','回复已发布')}
function notifications(){db.notificationsRead=true;save();render();modal(t('You are in the loop.','掌握最新动态。'),t('Updates from your learning workspace.','学习空间的最新消息。'),`<div class="deadline"><span class="deadline-icon">${icon('award')}</span><div><strong>${t('Requirements analysis · Grade available','需求分析 · 成绩已公布')}</strong><p>${t('Your instructor shared a score and feedback.','教师已发布成绩和反馈。')}</p><button class="small-link" onclick="closeModal();go('grades')">${t('View grade','查看成绩')}${icon('arrow')}</button></div></div><div class="deadline"><span class="deadline-icon">${icon('clock')}</span><div><strong>${t('Your scope plan is due November 6','范围计划将于11月6日截止')}</strong><p>${t('A small reminder to keep your project moving.','记得按时提交，让项目稳步推进。')}</p><button class="small-link" onclick="closeModal();go('assignments')">${t('View assignments','查看作业')}${icon('arrow')}</button></div></div>`)}
function help(){modal(t('A little help to get started.','轻松开始使用。'),t('Your connected learning and project workspace.','连接学习与项目协作的空间。'),`<div class="checklist"><label>${icon('book')}${t('Open a course, complete a lesson and save a private note.','打开课程、完成课时并保存个人笔记。')}</label><label>${icon('clipboard')}${t('Submit an assignment or try the three-question practice quiz.','提交作业，或试试三道题的知识测验。')}</label><label>${icon('folder')}${t('Move tasks across the board and build a weekly report.','移动看板任务并编写项目周报。')}</label><label>${icon('users')}${t('Use the avatar menu to view your profile or sign out.','在头像菜单中查看个人资料或退出登录。')}</label><label>${icon('globe')}${t('Switch between English and Chinese from the top bar.','在顶部切换英文与中文。')}</label></div><div class="form-note">${t('Prototype scope: browser-local data, sample learning content and illustrative analytics. Secure accounts, real file storage, email and cross-device collaboration are not connected.','原型范围：浏览器本地数据、示例课程与统计。尚未接入安全账户、真实文件存储、邮件和跨设备协作。')}</div><div class="modal-actions">${btn(t('Let’s get started','开始使用'),"closeModal()",'primary','arrow')}</div>`)}
function globalSearch(e){e.preventDefault();const q=new FormData(e.target).get('q').trim().toLowerCase();if(!q)return;let results=[...db.courses.filter(c=>!c.draft||db.role!=='student').map(c=>({title:txt(c.title),kind:t('Course','课程'),action:`closeModal();openCourse('${c.id}')`})),...db.tasks.map(a=>({title:txt(a.title),kind:t('Team task','团队任务'),action:"closeModal();projectTab='board';go('projects')"})),...resources.map(r=>({title:txt(r.title),kind:t('Resource','资源'),action:"closeModal();go('resources')"}))].filter(r=>r.title.toLowerCase().includes(q));modal(t('Find your next step.','找到你的下一步。'),t('Search results for “','搜索结果：“')+esc(q)+'”',results.length?results.map(r=>`<button class="deadline" style="width:100%;text-align:left" onclick="${r.action}"><span class="deadline-icon">${icon('search')}</span><div><strong>${esc(r.title)}</strong><p>${r.kind}</p></div></button>`).join(''):emptyState(t('No results yet','未找到结果'),t('Try “project”, “scope” or “report”.','试试“项目”“范围”或“周报”。')))}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('.search-top input')?.focus()}if(e.key==='Tab'&&$('.modal')){let focusable=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.offsetParent!==null);let first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
render();

function wireLabels(){document.querySelectorAll('.field').forEach((field,i)=>{const label=field.querySelector('label'),control=field.querySelector('input,textarea,select');if(label&&control){control.id ||= 'field-'+i;label.htmlFor=control.id}})}

void refreshAccountSession();
document.addEventListener('visibilitychange', () => { if (!document.hidden) void refreshAccountSession(); });
setInterval(() => { if (db.user && !document.hidden) void refreshAccountSession(); }, 30000);
